<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50">
		<!-- ============ HEADER ============ -->
		<div
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="{ name: 'StplUnitHilang' }"
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					title="Kembali"
					aria-label="Kembali"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>
				<span class="min-w-0 truncate font-medium text-ui-ink-gray-900"
					>Tambah STPL Unit Hilang</span
				>
			</div>
		</div>

		<!-- ============ FORM ============ -->
		<div class="flex flex-1 flex-col">
			<div class="app-container-narrow px-4 py-5 text-base md:px-6">
				<pre
					v-if="saveError"
					class="mb-4 rounded-md border border-ui-line-red-200 bg-ui-surface-red-50 px-3 py-2 text-sm text-ui-ink-red-700 whitespace-pre-wrap"
					>{{ saveError }}</pre
				>

				<section
					class="space-y-4 rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
				>
					<!-- Master Data Nasabah (searchable) -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Master Data Nasabah <span class="text-ui-ink-red-500">*</span>
						</label>
						<div class="relative">
							<input
								v-model="nasabahQuery"
								type="text"
								placeholder="Cari No Perjanjian / nama nasabah…"
								:class="inputClass"
								@focus="onNasabahFocus"
								@input="onNasabahSearch"
							/>
							<div
								v-if="nasabahOpen"
								class="absolute z-30 mt-1 max-h-56 w-full overflow-y-auto rounded-xl border border-ui-line-gray-200 bg-ui-surface shadow-lg"
							>
								<p v-if="nasabahSearching" class="px-3 py-2 text-xs text-ui-ink-gray-400">
									Mencari…
								</p>
								<p
									v-else-if="!nasabahResults.length"
									class="px-3 py-2 text-xs text-ui-ink-gray-400"
								>
									Tidak ada data.
								</p>
								<button
									v-for="r in nasabahResults"
									:key="r.name"
									type="button"
									class="block w-full px-3 py-2 text-left text-xs hover:bg-primary/5"
									@click="selectNasabah(r)"
								>
									<span class="font-semibold text-ui-ink-gray-800">{{
										r.nama_nasabah || r.name
									}}</span>
									<span class="block truncate text-ui-ink-gray-400">{{ r.name }}</span>
								</button>
							</div>
						</div>
						<div
							v-if="nasabahOpen"
							class="fixed inset-0 z-20"
							@click="nasabahOpen = false"
						/>
					</div>

					<!-- Preview nasabah terpilih (read-only, ikut tersimpan otomatis di server) -->
					<div
						v-if="form.master_data_nasabah"
						class="space-y-1.5 rounded-xl bg-ui-surface-gray-50 px-3 py-2.5 text-xs"
					>
						<p v-if="previewLoading" class="text-center text-ui-ink-gray-400">
							Memuat data nasabah…
						</p>
						<template v-else>
							<div
								v-for="p in previewRows"
								:key="p.label"
								class="flex items-start justify-between gap-3"
							>
								<span class="shrink-0 text-ui-ink-gray-500">{{ p.label }}</span>
								<span
									class="min-w-0 break-words text-right font-medium text-ui-ink-gray-800"
									>{{ p.value }}</span
								>
							</div>
						</template>
					</div>

					<!-- Tanggal STPL -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							Tanggal STPL <span class="text-ui-ink-red-500">*</span>
						</label>
						<input v-model="form.tanggal_stpl" type="date" :class="inputClass" />
					</div>

					<!-- File STPL (Attach, upload) -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500">
							File STPL <span class="text-ui-ink-red-500">*</span>
						</label>
						<div
							v-if="form.stpl_file"
							class="mb-2 flex items-center justify-between gap-2 rounded-md border border-ui-line-gray-200 bg-ui-surface-gray-50 px-3 py-2"
						>
							<a
								:href="form.stpl_file"
								target="_blank"
								rel="noopener"
								class="min-w-0 truncate text-sm font-medium text-primary hover:underline"
							>
								{{ fileName(form.stpl_file) }}
							</a>
							<button
								type="button"
								class="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-ui-ink-red-500 transition hover:bg-ui-surface-red-50"
								aria-label="Hapus file"
								@click="form.stpl_file = ''"
							>
								<svg
									xmlns="http://www.w3.org/2000/svg"
									viewBox="0 0 24 24"
									class="h-4 w-4"
									fill="none"
									stroke="currentColor"
									stroke-width="2"
									stroke-linecap="round"
									stroke-linejoin="round"
								>
									<path d="M3 6h18" />
									<path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6" />
									<path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
								</svg>
							</button>
						</div>
						<button
							type="button"
							:disabled="uploading"
							class="flex w-full items-center gap-2 rounded-md border border-dashed border-ui-line-gray-300 px-3 py-3 text-left text-sm text-ui-ink-gray-500 transition hover:border-primary disabled:opacity-50"
							@click="pickFile"
						>
							<svg
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-5 w-5 shrink-0"
								fill="none"
								stroke="currentColor"
								stroke-width="1.8"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
								<path d="M17 8l-5-5-5 5" />
								<path d="M12 3v12" />
							</svg>
							{{
								uploading
									? 'Mengunggah…'
									: form.stpl_file
									? 'Ganti file'
									: 'Pilih file (PDF/JPG/PNG, maks 3 MB)'
							}}
						</button>
						<input
							ref="fileInput"
							type="file"
							class="hidden"
							accept=".pdf,image/*"
							@change="onFileChange"
						/>
					</div>

					<!-- Catatan (opsional) -->
					<div>
						<label class="mb-1 block text-base font-medium text-ui-ink-gray-500"
							>Catatan</label
						>
						<textarea
							v-model="form.catatan"
							rows="3"
							placeholder="Catatan tambahan (opsional)"
							:class="[inputClass, 'resize-none']"
						/>
					</div>
				</section>
			</div>
		</div>

		<!-- ============ ACTION BAR ============ -->
		<div
			class="sticky bottom-0 z-20 flex gap-2 border-t border-ui-line-gray-200 bg-ui-surface px-4 py-3 md:px-6 bottom-bar"
			style="padding-bottom: calc(0.75rem + env(safe-area-inset-bottom))"
		>
			<RouterLink
				:to="{ name: 'StplUnitHilang' }"
				class="flex flex-1 items-center justify-center rounded-lg border border-ui-line-gray-300 bg-ui-surface py-2.5 text-sm font-medium text-ui-ink-gray-700"
			>
				Cancel
			</RouterLink>
			<button
				type="button"
				:disabled="saving || uploading"
				class="flex flex-1 items-center justify-center rounded-lg bg-primary py-2.5 text-sm font-medium text-ui-onPrimary transition hover:opacity-90 disabled:opacity-50"
				@click="submit"
			>
				{{ saving ? 'Menyimpan…' : 'Save' }}
			</button>
		</div>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken } from '../data/session'
import { notifyError, notifySuccess } from '../composables/toast'

const router = useRouter()
const DOCTYPE = 'STPL Unit Hilang'

function today() {
	const d = new Date()
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
		d.getDate()
	).padStart(2, '0')}`
}

const form = reactive({
	master_data_nasabah: '',
	tanggal_stpl: today(),
	stpl_file: '',
	catatan: '',
})
const saving = ref(false)
const saveError = ref('')

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// ---- Pemilih Master Data Nasabah ------------------------------------------
const nasabahQuery = ref('')
const nasabahOpen = ref(false)
const nasabahSearching = ref(false)
const nasabahResults = ref([])
let nasabahTimer = null

function onNasabahFocus() {
	nasabahOpen.value = true
	if (!nasabahResults.value.length) fetchNasabah('')
}
function onNasabahSearch() {
	nasabahOpen.value = true
	clearTimeout(nasabahTimer)
	nasabahTimer = setTimeout(() => fetchNasabah(nasabahQuery.value), 300)
}
async function fetchNasabah(q) {
	nasabahSearching.value = true
	try {
		const params = new URLSearchParams({
			doctype: 'Master Data Nasabah',
			fields: JSON.stringify(['name', 'nama_nasabah']),
			order_by: 'modified desc',
			limit_page_length: '20',
		})
		const t = (q || '').trim()
		if (t)
			params.set(
				'or_filters',
				JSON.stringify([
					['name', 'like', `%${t}%`],
					['nama_nasabah', 'like', `%${t}%`],
				])
			)
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		nasabahResults.value = json.message || []
	} catch (e) {
		nasabahResults.value = []
	} finally {
		nasabahSearching.value = false
	}
}

// ---- Preview nasabah terpilih ---------------------------------------------
const preview = reactive({
	nama_nasabah: '',
	no_perjanjian: '',
	nopol: '',
	cabang_jss: '',
})
const previewLoading = ref(false)
const previewRows = computed(() => [
	{ label: 'Nama Nasabah', value: preview.nama_nasabah || '—' },
	{ label: 'No Perjanjian', value: preview.no_perjanjian || '—' },
	{ label: 'Nopol', value: preview.nopol || '—' },
	{ label: 'Cabang JSS', value: preview.cabang_jss || '—' },
])
function resetPreview() {
	preview.nama_nasabah = ''
	preview.no_perjanjian = ''
	preview.nopol = ''
	preview.cabang_jss = ''
}
async function selectNasabah(r) {
	form.master_data_nasabah = r.name
	nasabahQuery.value = r.nama_nasabah || r.name
	nasabahOpen.value = false
	saveError.value = ''
	previewLoading.value = true
	resetPreview()
	try {
		const params = new URLSearchParams({
			doctype: 'Master Data Nasabah',
			filters: r.name,
			fieldname: JSON.stringify(['nama_nasabah', 'no_perjanjian', 'nopol', 'cabang_jss']),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const mdn = (await res.json())?.message || {}
		preview.nama_nasabah = mdn.nama_nasabah || r.nama_nasabah || ''
		preview.no_perjanjian = mdn.no_perjanjian || ''
		preview.nopol = mdn.nopol || ''
		preview.cabang_jss = mdn.cabang_jss || ''
	} catch (e) {
		/* preview gagal → biarkan '—'; server tetap isi snapshot saat save */
	} finally {
		previewLoading.value = false
	}
}

// ---- Upload File STPL ------------------------------------------------------
const fileInput = ref(null)
const uploading = ref(false)
function pickFile() {
	saveError.value = ''
	if (fileInput.value) {
		fileInput.value.value = ''
		fileInput.value.click()
	}
}
function fileName(url) {
	if (!url) return ''
	const clean = String(url).split('?')[0]
	return decodeURIComponent(clean.substring(clean.lastIndexOf('/') + 1)) || clean
}
async function onFileChange(e) {
	const file = e.target.files?.[0]
	if (!file) return
	const MAX_MB = 3
	if (file.size > MAX_MB * 1024 * 1024) {
		saveError.value = `Ukuran file maksimal ${MAX_MB} MB.`
		return
	}
	uploading.value = true
	try {
		const fd = new FormData()
		fd.append('file', file, file.name)
		fd.append('is_private', '1')
		const res = await fetch('/api/method/upload_file', {
			method: 'POST',
			credentials: 'include',
			headers: {
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: fd,
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
		form.stpl_file = json.message?.file_url || ''
	} catch (err) {
		saveError.value = err.message || String(err)
	} finally {
		uploading.value = false
	}
}

// ---- Simpan ----------------------------------------------------------------
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

function validate() {
	const missing = []
	if (!form.master_data_nasabah) missing.push('Master Data Nasabah')
	if (!form.tanggal_stpl) missing.push('Tanggal STPL')
	if (!form.stpl_file) missing.push('File STPL')
	return missing
}

async function submit() {
	saveError.value = ''
	const missing = validate()
	if (missing.length) {
		saveError.value = `Lengkapi: ${missing.join(', ')}`
		notifyError(saveError.value, 'Data belum lengkap')
		window.scrollTo({ top: 0, behavior: 'smooth' })
		return
	}
	saving.value = true
	try {
		await refreshCsrfToken()
		// Snapshot nasabah (no_perjanjian/nama/nopol/dst) diisi otomatis oleh
		// controller saat validate — cukup kirim field input.
		const doc = {
			doctype: DOCTYPE,
			master_data_nasabah: form.master_data_nasabah,
			tanggal_stpl: form.tanggal_stpl,
			stpl_file: form.stpl_file,
			catatan: form.catatan,
		}
		const res = await fetch('/api/method/frappe.client.insert', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		notifySuccess('STPL Unit Hilang berhasil dibuat.')
		const name = json.message?.name
		if (name) router.push({ name: 'StplUnitHilangDetail', params: { name } })
		else router.push({ name: 'StplUnitHilang' })
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
		window.scrollTo({ top: 0, behavior: 'smooth' })
	} finally {
		saving.value = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
})
</script>
